def sort_dedup_by_highest_score(records):
    best_by_id = {}

    for r in records:
        if "id" not in r:
            continue

        score = r.get("score")
        try:
            score = float(score)
        except (TypeError, ValueError):
            continue

        record_id = r["id"]
        if record_id not in best_by_id or score > best_by_id[record_id]["score"]:
            best_by_id[record_id] = {**r, "score": score}

    return sorted(best_by_id.values(), key=lambda x: x["score"])


