from collections import defaultdict

def group_and_sort_by_category(records):
    groups = defaultdict(list)

    for r in records:
        category = r.get("category")
        score = r.get("score")

        if category is None:
            continue
        try:
            score = float(score)
        except (TypeError, ValueError):
            continue

        groups[category].append({**r, "score": score})

    for category in groups:
        groups[category].sort(key=lambda x: x["score"])

    return dict(groups)


