import json

def _make_hashable(obj):
    if isinstance(obj, dict):
        return ("dict", tuple(sorted((k, _make_hashable(v)) for k, v in obj.items())))
    if isinstance(obj, list):
        return ("list", tuple(_make_hashable(x) for x in obj))
    if isinstance(obj, tuple):
        return ("tuple", tuple(_make_hashable(x) for x in obj))
    if isinstance(obj, set):
        return ("set", tuple(sorted(_make_hashable(x) for x in obj)))
    return ("scalar", obj)

def dedupe_preserve_order_generic(items):
    seen = set()
    result = []

    for item in items:
        key = _make_hashable(item)
        if key not in seen:
            seen.add(key)
            result.append(item)

    return result


